```swift
func generateDistinctPrimesInRange(min: Int, max: Int, count: Int) -> [Int] {
    // Helper function to check if a number is prime
    func isPrime(_ number: Int) -> Bool {
        if number <= 1 {
            return false
        }
        if number <= 3 {
            return true
        }
        if number % 2 == 0 || number % 3 == 0 {
            return false
        }
        var i = 5
        while i * i <= number {
            if number % i == 0 || number % (i + 2) == 0 {
                return false
            }
            i += 6
        }
        return true
    }

    // Generate all prime numbers within the range
    var primesInRange: [Int] = []
    for number in min...max {
        if isPrime(number) {
            primesInRange.append(number)
        }
    }

    // Check if it is possible to generate count distinct prime numbers
    if primesInRange.count < count {
        return []
    }

    // Return the first count distinct prime numbers
    return Array(primesInRange.prefix(count))
}
```

