  transform: rotateY(-180deg);
}
```
JavaScript 代码：
```javascript
let book = document.querySelector('.book');
let pages = document.querySelectorAll('.front-page, .back-page');
let frontPage = document.querySelector('.front-page');
let backPage = document.querySelector('.back-page');
document.addEventListener('DOMContentLoaded', () => {
  book.classList.remove('hiding');
});
book.addEventListener('click', () => {
  pages.forEach(page => {
    page.classList.add('flip');
  });
  setTimeout(() => {
    pages.forEach(page => {
      page.classList.add('hiding');
    });
    if (frontPage.classList.contains('flip')) {
      backPage.classList.remove('flip', 'hiding');
    } else {
      frontPage.classList.remove('flip', 'hiding');
    }
    setTimeout(() => {
      pages.forEach(page => {
        page.classList.remove('flip');
      });
    }, 0);
  }, 1000);
});
