for (size_t q = 0; q < sizeof(t_query_arr) / sizeof(t_query_arr[0]); q++) {
for (size_t u = 0; u < sizeof(t_update_arr) / sizeof(t_update_arr[0]); u++) {
reset();

total_queries = 0;
cache_hits = 0;

for (int i = 0; i < NUM_CLIENTS; i++) {
nodes[i].id = i;
